import{_ as o,o as t,c as d,a2 as i}from"./chunks/framework.D0_YsCyK.js";const u=JSON.parse('{"title":"通知系统全量审计（O8）","description":"","frontmatter":{},"headers":[],"relativePath":"audit/O8-notify.md","filePath":"audit/O8-notify.md","lastUpdated":1792449669000}'),n={name:"audit/O8-notify.md"};function r(c,e,l,a,s,h){return t(),d("div",null,[...e[0]||(e[0]=[i(`<h1 id="通知系统全量审计-o8" tabindex="-1">通知系统全量审计（O8） <a class="header-anchor" href="#通知系统全量审计-o8" aria-label="Permalink to &quot;通知系统全量审计（O8）&quot;">​</a></h1><ul><li>审计员：notify-auditor（子代理）</li><li>时间：2026-10-20</li><li>基线：main @ 1.0.7（含 M-001 等修复后）</li><li>参考手册：<code>doc/guide/notify.md</code></li><li>范围：<code>go-backend/internal/http/handler/notify.go</code>（448 行）、<code>notify_reports.go</code>（276 行）、<code>kernel_probe.go</code>（导入节点探测）、<code>kernel.go:1561</code>（内核错误）、<code>vite-frontend/src/pages/config/notify-card.tsx</code>、合同测试 <code>tests/contract/notify_contract_test.go</code></li><li>结论：<strong>P0 0 / P1 0 / P2 2 / P3 4</strong>。核心链路（SSRF 防护、去重、鉴权、敏感配置）扎实；问题集中在<strong>状态全放内存</strong>导致的重启语义缺口。</li></ul><hr><h2 id="p2" tabindex="-1">P2 <a class="header-anchor" href="#p2" aria-label="Permalink to &quot;P2&quot;">​</a></h2><h3 id="o8-001-面板重启时-已掉线节点永不告警-漏报" tabindex="-1">O8-001 面板重启时，已掉线节点永不告警（漏报） <a class="header-anchor" href="#o8-001-面板重启时-已掉线节点永不告警-漏报" aria-label="Permalink to &quot;O8-001 面板重启时，已掉线节点永不告警（漏报）&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/notify.go:322-344</code>（<code>notifyNodeOffline</code>）、<code>go-backend/internal/http/handler/handler.go:151-152</code></li><li><strong>复现步骤</strong>： <ol><li>节点 A 在线，通知已启用并勾选&quot;节点掉线 / 恢复&quot;。</li><li>节点 A 断开连接（<code>SetNodeOfflineHook</code> 触发 <code>notifyNodeOffline</code>，90s 定时器 pending）。</li><li>在 90s 内重启面板（或 90s 后、告警已发出后重启——两种情况都丢）。</li><li>重启后节点 A 一直不恢复。</li><li><strong>结果</strong>：永远收不到&quot;节点掉线&quot;告警。<code>offlineTimers</code>/<code>offlineAlerted</code> 是 <code>notifier</code> 的内存 map，重启即清空；重启后该节点在本进程内从未&quot;断开&quot;过，没有事件能再次触发 <code>notifyNodeOffline</code>。</li></ol></li><li><strong>影响</strong>：面板升级/重启窗口内掉线的节点会被静默漏报，管理员只能靠每日汇总里的&quot;节点在线：X / Y&quot;发现。</li><li><strong>手册对照</strong>：手册称&quot;节点断开超过 90 秒才提醒&quot;，未说明重启语义；但从运维角度，重启不应吞掉正在发生的故障告警。</li><li><strong>建议</strong>：启动时对超过 90s 未见心跳的节点补一次 <code>notifyNodeOffline</code>（或把 <code>offlineAlerted</code> 持久化）。</li></ul><h3 id="o8-002-通知发送无重试-失败即丢失" tabindex="-1">O8-002 通知发送无重试，失败即丢失 <a class="header-anchor" href="#o8-002-通知发送无重试-失败即丢失" aria-label="Permalink to &quot;O8-002 通知发送无重试，失败即丢失&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/notify.go:150-162</code>（<code>notify</code>）、<code>notify_reports.go:213-224</code>（<code>maybeDailyReport</code>）</li><li><strong>复现步骤</strong>： <ol><li>启用通知，Webhook 指向一个会超时/5xx 的地址（或面板出网瞬断）。</li><li>触发任一事件（节点掉线/测试通知）。</li><li><strong>结果</strong>：<code>notify()</code> 起 goroutine 发送，<code>send</code> 返回 err 后仅 <code>log.Printf(&quot;notify %s failed: %v&quot;)</code>，无重试、无持久化队列，告警丢失。</li><li>每日汇总更甚：<code>maybeDailyReport</code> 先 <code>UpsertConfig(notify_daily_last, today)</code> <strong>再</strong> <code>h.notify(...)</code>——发送失败当天不会再试。</li></ol></li><li><strong>手册对照</strong>：手册未承诺重试；但&quot;边界条件：通知失败重试&quot;在任务书中被明确要求审查，故列为 P2。</li><li><strong>建议</strong>：至少对 <code>maybeDailyReport</code> 改为&quot;发送成功后再标记&quot;（<code>notify</code> 是异步的，可改为同步 <code>send</code> 后再落盘）；或引入有限重试（3 次、指数退避）。</li></ul><hr><h2 id="p3" tabindex="-1">P3 <a class="header-anchor" href="#p3" aria-label="Permalink to &quot;P3&quot;">​</a></h2><h3 id="o8-003-删除节点时未清理-notifier-状态-幽灵告警-内存泄漏" tabindex="-1">O8-003 删除节点时未清理 notifier 状态（幽灵告警 + 内存泄漏） <a class="header-anchor" href="#o8-003-删除节点时未清理-notifier-状态-幽灵告警-内存泄漏" aria-label="Permalink to &quot;O8-003 删除节点时未清理 notifier 状态（幽灵告警 + 内存泄漏）&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/notify.go:322-344</code>、<code>go-backend/internal/http/handler/mutations.go:5058</code>（<code>deleteNodeByID</code>）</li><li><strong>复现步骤</strong>： <ol><li>节点 A 断开，90s 定时器 pending（<code>offlineTimers[A]</code> 存在）。</li><li>在面板删除节点 A（<code>deleteNodeByID</code> 全程未触碰 <code>h.notifier</code>——已用 grep 确认零引用）。</li><li>定时器触发：<code>IsNodeOnline(A)</code> 为 false → <code>offlineAlerted[A]=true</code> → 发送&quot;节点掉线&quot;，<code>nodeLabel(A)</code> 查库失败退化为 <code>&quot;节点 {id}&quot;</code>。</li><li><strong>结果</strong>：给已删除的节点发了一条无意义的掉线告警；<code>offlineTimers</code>/<code>offlineAlerted</code> 的条目永久残留（map 无上限，长期运行缓慢泄漏）。</li></ol></li><li><strong>建议</strong>：<code>deleteNodeByID</code> 内调用 <code>h.notifier</code> 清理该节点定时器与标记（需给 <code>notifier</code> 加一个 <code>forgetNode(id)</code> 方法）。</li></ul><h3 id="o8-004-已过期的节点-用户-订阅每次重启后重新告警" tabindex="-1">O8-004 已过期的节点/用户/订阅每次重启后重新告警 <a class="header-anchor" href="#o8-004-已过期的节点-用户-订阅每次重启后重新告警" aria-label="Permalink to &quot;O8-004 已过期的节点/用户/订阅每次重启后重新告警&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>notify.go:356-390</code>（<code>checkNodeExpiry</code>）、<code>notify_reports.go:60-124</code>（<code>checkUserReminders</code>）</li><li><strong>复现步骤</strong>： <ol><li>某节点 <code>expiry_time</code> 为一个月前（<code>ExpiryReminderDismissed=0</code>）。</li><li><code>checkNodeExpiry</code>：<code>left := expiry.Sub(now)</code> 为负，<code>left &gt; notifyExpiryWindow</code>（3 天）为 false → <strong>不跳过</strong> → <code>expiryAlerted</code> 内存去重（进程内只发一次）→ 发送&quot;节点已到期&quot;。</li><li>重启面板 → <code>expiryAlerted</code> 清空 → 再次发送&quot;节点已到期&quot;。</li><li>用户侧同理：<code>checkUserReminders</code> 的 <code>exp:{id}:{expTime}</code> key、<code>sub:{id}:{expTime}</code> key 均为内存去重；<code>time.UnixMilli(u.ExpTime).Sub(now) &lt;= window</code> 对早已过期的用户同样成立。</li></ol></li><li><strong>手册对照</strong>：手册只说&quot;到期前 3 天内提醒一次&quot;，未定义&quot;已过期很久&quot;的行为；当前实现把&quot;已过期&quot;当作需要反复提醒的事项，但去重又只在内存里，导致语义 = &quot;每次重启 spam 一次&quot;。</li><li><strong>建议</strong>：二选一并写进手册——(a) 已过期超过 N 天的不再提醒；(b) 去重持久化（config 表存 <code>notify_expiry_sent:{kind}:{id}:{expTime}</code>）。</li></ul><h3 id="o8-005-内核错误通知无-同一问题只提醒一次-去重" tabindex="-1">O8-005 内核错误通知无&quot;同一问题只提醒一次&quot;去重 <a class="header-anchor" href="#o8-005-内核错误通知无-同一问题只提醒一次-去重" aria-label="Permalink to &quot;O8-005 内核错误通知无&quot;同一问题只提醒一次&quot;去重&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/kernel.go:1556-1562</code></li><li><strong>代码</strong>：<div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> newStatus </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kernelStatusError </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k.Status </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kernelStatusError {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    h.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">notify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(notifyEventKernelError, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;内核运行出错&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, msg)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><strong>问题</strong>：仅靠&quot;状态翻转&quot;去重。内核在 error↔ok 间抖动（agent 上报不稳定、配置反复应用失败）时，每次翻回 error 都发一条，没有类似 <code>alertOnce</code> 的收敛。节点掉线有 <code>offlineAlerted</code>、流量有 <code>alerted</code>，唯独内核错误没有。</li><li><strong>手册对照</strong>：手册&quot;同一个问题只提醒一次，恢复后才会再次提醒&quot;——抖动场景下&quot;恢复&quot;可能只是 agent 的一次误报，会导致刷屏。</li><li><strong>建议</strong>：给 kernel_error 加 <code>alertOnce(&quot;kerr:{nodeID}:{kernelType}&quot;)</code>，在状态恢复 ok 时 <code>clearAlerts</code>。</li></ul><h3 id="o8-006-notify-events-none-靠命名巧合实现-全不选" tabindex="-1">O8-006 <code>notify_events=&quot;none&quot;</code> 靠命名巧合实现&quot;全不选&quot; <a class="header-anchor" href="#o8-006-notify-events-none-靠命名巧合实现-全不选" aria-label="Permalink to &quot;O8-006 \`notify_events=&quot;none&quot;\` 靠命名巧合实现&quot;全不选&quot;&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>vite-frontend/src/pages/config/notify-card.tsx:108</code>、<code>go-backend/internal/http/handler/notify.go:133-147</code></li><li><strong>问题</strong>：前端取消全选时存字面量 <code>&quot;none&quot;</code>；后端 <code>notifyConfig</code> 把它 split 后逐个比对事件 key，&quot;none&quot; 恰好不等于任何事件 → 禁用。功能正确，但属于脆弱的隐式约定：未来若新增 key 为 <code>none</code> 的事件会静默启用；且 <code>&quot;none,node_offline&quot;</code> 这种中间态（先全不选再勾一个）会把无意义的 <code>&quot;none&quot;</code> 永久留在配置里。</li><li><strong>建议</strong>：后端在 <code>notifyConfig</code> 里显式识别 <code>&quot;none&quot;</code>（或前端全不选时存空字符串 + 单独的 <code>notify_enabled</code> 已可表达，实际当前 <code>notify_enabled=false</code> 就够了）。</li></ul><hr><h2 id="已验证通过-手册逐项对照" tabindex="-1">已验证通过（手册逐项对照） <a class="header-anchor" href="#已验证通过-手册逐项对照" aria-label="Permalink to &quot;已验证通过（手册逐项对照）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>手册条目</th><th>实现</th><th>结论</th></tr></thead><tbody><tr><td>节点掉线超 90s 才提醒，恢复再报</td><td><code>nodeOfflineGrace=90s</code> 定时器；<code>notifyNodeOnline</code> 仅当 <code>offlineAlerted</code> 时发恢复</td><td>✅</td></tr><tr><td>导入节点连续 2 次失败（约 6 分钟）</td><td><code>notifyInboundDownStreak=2</code>，<code>externalProbeInterval=3min</code>；<code>track()</code> 状态机；恢复通知</td><td>✅（合同测试 <code>TestNotifyImportedNodeDownContract</code> 覆盖：一次失败不报、持续只报一次、恢复报、未勾选事件不报）</td></tr><tr><td>内核出错附带错误信息</td><td><code>kernel.go:1561</code>，错误截断 300 字</td><td>✅（去重见 O8-005）</td></tr><tr><td>节点到期前 3 天提醒一次，可在节点页关闭</td><td><code>notifyExpiryWindow=3*24h</code>；<code>expiryAlerted[id]==expTime</code> 去重；<code>ExpiryReminderDismissed==1</code> 跳过</td><td>✅（重启语义见 O8-004）</td></tr><tr><td>用户流量 90%/用完、3 天内到期；分享订阅同理</td><td><code>checkUserReminders</code> + <code>checkSubQuota</code>；<code>alertOnce(&quot;flow:{id}:warn/full&quot;)</code>；低于 90% 时 <code>clearAlerts</code> 恢复</td><td>✅</td></tr><tr><td>每日汇总定时发送</td><td><code>maybeDailyReport</code>：整点匹配 + <code>notify_daily_last</code> 持久化防重发；<code>notify_daily_hour</code> 前后端双重 0–23 校验</td><td>✅（失败语义见 O8-002）</td></tr><tr><td>同一问题只提醒一次</td><td><code>offlineAlerted</code> / <code>alerted</code> / <code>expiryAlerted</code> 三套内存去重</td><td>✅（持久化缺口见 O8-001/O8-004）</td></tr><tr><td>Webhook JSON 字段</td><td><code>event/title/message/text/time/app</code>，<code>text=[App] Title\\nMessage\\n时间：...</code></td><td>✅ 与手册示例一致；<code>event</code> 枚举含手册列出的 6 种 + <code>test</code></td></tr><tr><td>返回 2xx 视为成功</td><td><code>sendWebhook</code>：<code>status&lt;200 || &gt;=300</code> 即失败</td><td>✅</td></tr><tr><td>Telegram 反代地址</td><td><code>notify_telegram_api_base</code> 为空回退 <code>https://api.telegram.org</code>；<code>sendTelegram</code> 拼 <code>&lt;base&gt;/bot&lt;Token&gt;/sendMessage</code></td><td>✅</td></tr><tr><td>发送测试用未保存的表单值</td><td><code>notifyTest</code> 以请求体优先、缺省回退已保存配置</td><td>✅（合同测试覆盖）</td></tr><tr><td>Bot Token/Webhook 仅管理员可见、不进备份</td><td><code>IsSensitiveConfigKey</code> 含两 key；<code>handler.go:537/1129/1172</code> 非 admin 过滤；备份过滤</td><td>✅（合同测试覆盖 token 不泄漏）</td></tr><tr><td>Webhook SSRF 防护（LAD26-001 复审）</td><td><code>validateNotifyURL</code>：拒非 http/https、云元数据地址（含 IP 字面量与 DNS 解析后逐 IP 检查）；<code>CheckRedirect</code> 同样校验、最多 5 跳（R5R26-001）</td><td>✅ 复审通过</td></tr><tr><td>URL 脱敏（LAD26-017 复审）</td><td><code>post()</code> 错误路径返回固定文案（&quot;通知地址无效/请求超时/无法连接&quot;），不含 URL/token；校验错误（&quot;通知地址…&quot;开头）可透出</td><td>✅ 复审通过；合同测试断言失败信息不含 token</td></tr><tr><td>事件开关：空 = 全开</td><td><code>notifyConfig</code>：<code>notify_events</code> 为空跳过过滤；前端全选时存 <code>&quot;&quot;</code></td><td>✅</td></tr><tr><td>非 admin 调 <code>/api/v1/notify/test</code> 被拒绝</td><td>中间件鉴权</td><td>✅（合同测试覆盖）</td></tr></tbody></table><p><strong>说明</strong>：</p><ul><li>任务书提到&quot;Bark/邮件&quot;渠道：实际代码与手册中<strong>没有</strong> Bark/邮件原生渠道，只有 Telegram + Webhook 两种；Bark/邮件是通过 Webhook 的 <code>text</code> 字段转发对接的（手册原文如此）。实现与手册一致，无缺失。</li><li>合同测试 <code>TestNotifyTestEndpointContract</code>、<code>TestNotifyImportedNodeDownContract</code> 均通过（实测）。</li><li>未发现 P0/P1：通知是&quot;尽力而为&quot;的辅助通道，无认证绕过、无 SSRF 绕过、无数据损坏类问题。</li></ul><hr><h2 id="未能验证" tabindex="-1">未能验证 <a class="header-anchor" href="#未能验证" aria-label="Permalink to &quot;未能验证&quot;">​</a></h2><ul><li>真实 Telegram Bot 发送（无外网凭据；<code>sendTelegram</code> 的请求构造与合同测试的 mock server 断言一致）。</li><li>面板重启场景（O8-001/O8-004）为代码路径推导，未做真机重启实测。</li><li>高频抖动下的内核错误刷屏量级（O8-005）为逻辑推导。</li></ul>`,26)])])}const f=o(n,[["render",r]]);export{u as __pageData,f as default};
